mapper.delete:
WITH principal_ids AS MATERIALIZED (
    SELECT id FROM iam_principal WHERE subject_id = #{subjectId}
), deleted_roles AS (
    DELETE FROM iam_principal_role WHERE principal_id IN (SELECT id FROM principal_ids)
), account_ids AS MATERIALIZED (
    SELECT id FROM iam_account WHERE subject_id = #{subjectId}
), credential_ids AS MATERIALIZED (
    SELECT id FROM iam_credential WHERE account_id IN (SELECT id FROM account_ids)
), deleted_passwords AS (
    DELETE FROM iam_password WHERE credential_id IN (SELECT id FROM credential_ids)
), deleted_credentials AS (
    DELETE FROM iam_credential WHERE account_id IN (SELECT id FROM account_ids)
), deleted_identifiers AS (
    DELETE FROM iam_account_identifier WHERE account_id IN (SELECT id FROM account_ids)
), deleted_accounts AS (
    DELETE FROM iam_account WHERE id IN (SELECT id FROM account_ids)
), deleted_contacts AS (
    DELETE FROM iam_contact WHERE subject_id = #{subjectId}
), deleted_memberships AS (
    DELETE FROM iam_tenant_membership WHERE subject_id = #{subjectId}
)
DELETE FROM iam_principal WHERE subject_id = #{subjectId};

