mapper.select:
SELECT account.id AS account_id, account.scope_type AS account_scope_type, account.scope_id AS account_scope_id, account.second_factor_required, subject.id AS subject_id, subject.display_name AS subject_display_name, p.id AS principal_id, p.principal_type, p.tenant_id, p.display_name AS principal_display_name, r.code AS role_code, effective_permission.code AS permission_code FROM iam_account account INNER JOIN iam_subject subject ON subject.id = account.subject_id AND subject.status = 'ACTIVE' AND subject.deleted = 0 INNER JOIN iam_principal p ON p.subject_id = subject.id AND p.status = 'ACTIVE' AND p.deleted = 0 AND (account.scope_type = 'GLOBAL' OR p.principal_type = 'DEFAULT' OR (p.principal_type = 'TENANT' AND p.tenant_id = account.scope_id)) LEFT JOIN iam_tenant_membership membership ON membership.id = p.membership_id AND membership.subject_id = p.subject_id AND membership.tenant_id = p.tenant_id AND membership.deleted = 0 LEFT JOIN iam_tenant tenant ON tenant.id = p.tenant_id LEFT JOIN iam_principal_role pr ON pr.principal_id = p.id LEFT JOIN iam_role r ON r.id = pr.role_id AND r.status = 'ACTIVE' AND r.deleted = 0 AND ((p.principal_type = 'TENANT' AND r.tenant_id = p.tenant_id) OR (p.principal_type <> 'TENANT' AND r.tenant_id IS NULL)) LEFT JOIN LATERAL ( SELECT permission.code FROM iam_permission permission WHERE permission.deleted = 0 AND (permission.granted_by_default = TRUE OR EXISTS ( SELECT 1 FROM iam_role_permission role_permission WHERE role_permission.role_id = r.id AND role_permission.permission_id = permission.id )) ) effective_permission ON TRUE WHERE account.id IN
#{accountId}
AND account.status = 'ACTIVE' AND account.deleted = 0 AND ((p.principal_type = 'TENANT' AND membership.status = 'ACTIVE' AND tenant.status = 'ACTIVE' AND tenant.deleted = 0) OR (p.principal_type <> 'TENANT' AND p.tenant_id IS NULL)) ORDER BY account.id, p.principal_type, p.tenant_id NULLS FIRST, p.id, r.code, effective_permission.code

SELECT credential.id AS credential_id, credential.account_id, account.subject_id, credential.credential_type, credential.status, credential.created_at, credential.updated_at, credential.version, credential.deleted FROM iam_credential credential INNER JOIN iam_account account ON account.id = credential.account_id AND account.deleted = 0 WHERE account.subject_id IN
#{subjectId}
AND credential.credential_type IN
#{credentialType}
AND credential.deleted = 0 ORDER BY account.subject_id, credential.account_id, credential.credential_type, credential.id

SELECT credential.id AS credential_id, credential.account_id, account.subject_id, credential.credential_type, identifier.value AS identifier, credential.deleted FROM iam_credential credential INNER JOIN iam_account account ON account.id = credential.account_id LEFT JOIN LATERAL ( SELECT value FROM iam_account_identifier WHERE account_id = account.id AND status = 'ACTIVE' AND deleted = 0 ORDER BY CASE WHEN identifier_type = 'USERNAME' THEN 0 ELSE 1 END, id LIMIT 1 ) identifier ON TRUE WHERE credential.id IN
#{credentialId}
ORDER BY credential.id

