mapper.delete:
WITH principal_ids AS MATERIALIZED (
    SELECT id
    FROM iam_principal
    WHERE tenant_id = #{tenantId}
      AND principal_type = 'TENANT'
      AND deleted = 1
), role_ids AS MATERIALIZED (
    SELECT id
    FROM iam_role
    WHERE tenant_id = #{tenantId}
      AND deleted = 1
), deleted_principal_roles AS (
    DELETE FROM iam_principal_role
    WHERE principal_id IN (SELECT id FROM principal_ids)
       OR role_id IN (SELECT id FROM role_ids)
), deleted_role_permissions AS (
    DELETE FROM iam_role_permission WHERE role_id IN (SELECT id FROM role_ids)
), deleted_roles AS (
    DELETE FROM iam_role WHERE id IN (SELECT id FROM role_ids)
), deleted_memberships AS (
    DELETE FROM iam_tenant_membership
    WHERE tenant_id = #{tenantId}
      AND deleted = 1
)
DELETE FROM iam_principal WHERE id IN (SELECT id FROM principal_ids)

mapper.select:
SELECT relation.principal_id, role.id AS role_id, role.code AS role_code, role.name AS role_name FROM iam_principal_role relation INNER JOIN iam_role role ON role.id = relation.role_id AND role.tenant_id IS NULL AND role.status = 'ACTIVE' AND role.deleted = 0 WHERE relation.principal_id IN
#{principalId}
ORDER BY relation.principal_id, role.name, role.code, role.id

SELECT DISTINCT ON (code) id, parent_id, code, name_key, permission_type, sort_order, granted_by_default, created_at, updated_at, version, deleted FROM iam_permission WHERE code IN
#{code}
ORDER BY code, deleted, id DESC

