    status = #{status},
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{roleId}
  AND version = #{version}
  AND deleted = 0


        AND tenant_id IS NULL


        AND tenant_id = #{tenantId}

UPDATE iam_role SET deleted = 1, updated_at = CURRENT_TIMESTAMP, version = version + 1 WHERE id = #{roleId} AND version = #{version} AND built_in = FALSE AND deleted = 0 AND NOT EXISTS ( SELECT 1 FROM iam_principal_role principal_role INNER JOIN iam_principal principal ON principal.id = principal_role.principal_id AND principal.deleted = 0 WHERE principal_role.role_id = iam_role.id )
AND tenant_id IS NULL
AND tenant_id = #{tenantId}

mapper.select:
SELECT role.id AS role_id, ( SELECT COUNT(DISTINCT principal_role.principal_id) FROM iam_principal_role principal_role INNER JOIN iam_principal principal ON principal.id = principal_role.principal_id AND principal.deleted = 0 WHERE principal_role.role_id = role.id ) AS principal_count, ( SELECT COUNT(*) FROM iam_role_permission role_permission INNER JOIN iam_permission permission ON permission.id = role_permission.permission_id AND permission.deleted = 0 WHERE role_permission.role_id = role.id ) AS permission_count FROM iam_role role WHERE role.id IN
#{roleId}
ORDER BY role.id
